                  },
                  "files": {
                    "brew.py": "#!/usr/bin/env python3\n\"\"\"The Homebrew board: what `brew outdated` lists, as MenuSprite blocks. The face's value runs this same command\nand reads the first block's figure (path 0.value), so one `brew outdated` feeds the menu bar and the board.\"\"\"\nimport json\nimport os\nimport subprocess\n\ndone = subprocess.run([\"brew\", \"outdated\", \"--json=v2\"], capture_output=True, text=True, timeout=55,\n                      env=dict(os.environ, HOMEBREW_NO_AUTO_UPDATE=\"1\"))\nif done.returncode != 0:\n    # brew prints tap warnings first; its reason for failing comes last.\n    reason = (done.stderr.strip().splitlines() or [\"brew outdated failed\"])[-1]\n    print(json.dumps([{\"text\": \"brew outdated failed\", \"font\": \"headline\", \"icon\": \"exclamationmark.triangle\"},\n                      {\"text\": reason[:200].replace(\"{\", \"{\\u200b\"), \"font\": \"caption\", \"color\": \"gray\"}]))\n    raise SystemExit(0)\n\noutdated = json.loads(done.stdout)\nformulae, casks = outdated.get(\"formulae\", []), outdated.get(\"casks\", [])\n\n\ndef short(version):\n    return str(version).split(\",\")[0]\n\n\ndef rows(items, limit=10):\n    result = [{\"name\": item[\"name\"] + (\" (pinned)\" if item.get(\"pinned\") else \"\"),\n               \"value\": \"%s → %s\" % (short((item.get(\"installed_versions\") or [\"?\"])[-1]), short(item.get(\"current_version\", \"?\")))}\n              for item in items[:limit]]\n    if len(items) > limit:\n        result.append({\"name\": \"and %d more\" % (len(items) - limit), \"value\": \"\"})\n    return result\n\n\ntotal = len(formulae) + len(casks)\nblocks = [{\"value\": total, \"caption\": \"Upgrades waiting\",\n           \"detail\": \"%d formulae · %d apps\" % (len(formulae), len(casks)) if total else \"Everything is up to date\"}]\nif formulae:\n    blocks.append({\"card\": [{\"stats\": rows(formulae)}], \"title\": \"Formulae\"})\nif casks:\n    blocks.append({\"card\": [{\"stats\": rows(casks)}], \"title\": \"Apps\"})\nprint(json.dumps(blocks))\n",
                    "upgrade.command": "#!/bin/zsh\n# Terminal's own PATH may not include Homebrew (a fresh shell profile), so set it up here.\neval \"$(/opt/homebrew/bin/brew shellenv 2>/dev/null || /usr/local/bin/brew shellenv 2>/dev/null)\"\n# Opened in Terminal by the board's \"Upgrade all\" button, so a long upgrade runs where it can be watched.\nbrew update && brew upgrade\n# Tell MenuSprite it is done, so the menu bar shows the new count now. This folder's name is the sprite's id.\nfor m in menusprite ~/Applications/MenuSprite.app/Contents/Helpers/menusprite /Applications/MenuSprite.app/Contents/Helpers/menusprite; do\n  [[ -x ${commands[$m]:-$m} ]] && { \"${commands[$m]:-$m}\" refresh \"${0:A:h:t}\" >/dev/null; break }\ndone\necho\nread -sk '?Done. Press any key to close this window.'\n"
                  }
                }
                """#),
        Example(name: "network-switches", summary: "Switches for Tailscale and Wi-Fi; three values that read one tailscale call; a copyable address",
                json: #"""
                {
                  "menusprite": 1,
                  "name": "Network switches",
                  "icon": "network",
                  "values": [
                    {
                      "id": "ts",
                      "name": "Tailscale",
                      "command": "tailscale status --json",
                      "every": "1m",
                      "parse": "json",
                      "path": "BackendState"
                    },
                    {
                      "id": "address",
                      "name": "Tailscale IP",
                      "command": "tailscale status --json",
                      "every": "1m",
                      "parse": "json",
                      "path": "Self.TailscaleIPs.0"
                    },
                    {
                      "id": "tailnet",
                      "name": "Tailnet",
                      "command": "tailscale status --json",
                      "every": "1m",
                      "parse": "json",
                      "path": "CurrentTailnet.Name"
                    },
                    {
                      "id": "peers",
                      "name": "Devices online",
                      "command": "tailscale status --json | jq '[.Peer[]? | select(.Online)] | length'",
                      "every": "1m",
                      "parse": "number"
                    },
                    {"id": "wifi", "name": "Wi-Fi", "command": "./wifi.sh", "every": "30s"}
                  ],
                  "face": {"row": [{"icon": "network", "id": "glyph", "size": 14}]},
                  "rules": [
                    {
                      "name": "Tailscale",
                      "cases": [
                        {
                          "when": "ts is missing",
                          "then": [
                            {"target": "glyph", "icon": "exclamationmark.triangle", "opacity": 0.6},
                            {"target": "tailscaleCard", "hide": true}
                          ]
                        },
                        {
                          "when": "ts != Running",
                          "then": [
                            {"target": "glyph", "icon": "network.slash", "opacity": 0.5},
                            {"target": "tailscaleCard", "hide": true}
                          ]
                        }
                      ]
                    }
                  ],
                  "board": {
                    "width": 340,
                    "blocks": [
                      {
                        "card": [
                          {
                            "toggle": "Tailscale",
                            "icon": "network",
                            "value": "ts",
                            "on": "tailscale up",
                            "off": "tailscale down",
                            "timeout": 60
                          },
                          {"toggle": "Wi-Fi", "icon": "wifi", "value": "wifi", "on": "./wifi.sh on", "off": "./wifi.sh off"}
                        ],
                        "title": "Switches"
                      },
                      {
                        "card": [
                          {"stats": ["tailnet", "peers"]},
                          {
                            "row": [
                              {"text": "{address}", "font": "mono", "lines": 1},
                              {"text": "Copy", "icon": "doc.on.doc", "color": "blue", "copy": "{address}", "fit": true}
                            ]
                          }
                        ],
                        "title": "Tailscale",
                        "id": "tailscaleCard"
                      },
                      {"button": "Tailscale admin", "icon": "safari", "open": "https://login.tailscale.com/admin/machines"}
                    ]
                  },
                  "files": {
                    "wifi.sh": "#!/bin/zsh -f\n# wifi.sh prints \"On\" or \"Off\"; wifi.sh on|off switches Wi-Fi. Finds the Wi-Fi device, which is not always en0.\ndevice=$(networksetup -listallhardwareports | awk '/Wi-Fi/{getline; print $2; exit}')\n[[ -n $device ]] || { echo \"No Wi-Fi hardware\" >&2; exit 1 }\nif [[ -n $1 ]]; then\n  networksetup -setairportpower \"$device\" \"$1\"\nelse\n  networksetup -getairportpower \"$device\" | awk '{print $NF}'\nfi\n"
                  }
                }
                """#),
        Example(name: "system-dashboard", summary: "CPU and memory on two face lines; tiles, charts, a disk gauge and the process list, from readings only",
                json: #"""
                {
                  "menusprite": 1,
                  "name": "System",
                  "icon": "cpu",
                  "every": 2,
                  "values": [
                    {"id": "cpu", "reading": "cpu.usage", "name": "CPU"},
                    {"id": "mem", "reading": "memory.usage", "name": "Memory"},
                    {"id": "pressure", "reading": "memory.pressure", "name": "Pressure"},
                    {"id": "power", "reading": "sensor.PSTR", "name": "Power"},
                    {"id": "temp", "reading": "sensor.cpuTemperature", "name": "CPU temperature"},
                    {"id": "load", "reading": "cpu.load1", "name": "Load (1 min)"},
                    {"id": "down", "reading": "network.download", "name": "Download"},
                    {"id": "up", "reading": "network.upload", "name": "Upload"},
                    {"id": "disk", "reading": "disk.usage", "name": "Disk"},
                    {"id": "free", "reading": "disk.available", "name": "Free"},
                    {"id": "uptime", "reading": "system.uptime", "name": "Uptime"}
                  ],
                  "face": {
                    "column": [
                      {"text": "CPU {cpu}", "id": "cpuText", "size": 9, "weight": "medium", "align": "leading"},
                      {"text": "MEM {mem}", "id": "memText", "size": 9, "weight": "medium", "align": "leading"}
                    ]
                  },
                  "rules": [
                    {"name": "Busy CPU", "when": "cpu >= 85", "then": [{"target": "cpuText", "color": "orange"}]},
                    {
                      "name": "Memory pressure",
                      "cases": [
                        {
                          "when": "pressure == Critical",
                          "then": [{"target": "memText", "color": "red"}, {"target": "memValue", "color": "red"}]
                        },
                        {
                          "when": "pressure == Warning",
                          "then": [{"target": "memText", "color": "orange"}, {"target": "memValue", "color": "orange"}]
                        }
                      ]
                    },
                    {"name": "Disk nearly full", "when": "disk >= 90", "then": [{"target": "diskGauge", "color": "orange"}]}
                  ],
                  "board": {
                    "width": 380,
                    "blocks": [
                      {
                        "row": [
                          {"value": "mem", "id": "memValue", "caption": "Memory", "detail": "{pressure}"},
                          {"value": "power", "caption": "System power", "detail": "CPU {temp}"},
                          {"value": "uptime", "caption": "Up for", "detail": "load {load}"}
                        ]
                      },
                      {
                        "card": [
                          {"chart": "cpu", "caption": "CPU", "height": 40},
                          {"chart": "down", "caption": "Download", "height": 32, "color": "teal"},
                          {"chart": "up", "caption": "Upload", "height": 32, "color": "indigo"}
                        ],
                        "title": "Recent"
                      },
                      {
                        "card": [{"gauge": "disk", "id": "diskGauge", "caption": "Startup disk", "detail": "{disk} used · {free} free"}],
                        "title": "Storage"
                      },
                      {"card": [{"processes": "cpu", "limit": 6}], "title": "Top processes"},
                      {"button": "Activity Monitor", "icon": "waveform.path.ecg", "app": "Activity Monitor"}
                    ]
                  }
                }
                """#),
        Example(name: "weather", summary: "Temperature and a sky icon from one wttr.in request; a forecast board with an icon per day",
                json: #"""
                {
                  "menusprite": 1,
                  "name": "Weather",
                  "icon": "cloud.sun.fill",
                  "values": [
                    {
                      "id": "temp",
                      "name": "Temperature",
                      "command": "./now.sh",
                      "every": "30m",
                      "timeout": 15,
                      "parse": "json",
                      "path": "current_condition.0.temp_C",
                      "suffix": "°"
                    },
                    {
                      "id": "sky",
                      "name": "Sky",
                      "command": "./now.sh",
                      "every": "30m",
                      "timeout": 15,
                      "parse": "json",
                      "path": "current_condition.0.weatherDesc.0.value"
                    }
                  ],
                  "face": {"row": [{"icon": "sun.max.fill", "id": "skyIcon", "size": 13}, {"text": "{temp}", "id": "tempText"}]},
                  "rules": [
                    {
                      "name": "Sky icon",
                      "cases": [
                        {"when": "sky contains thunder", "then": [{"target": "skyIcon", "icon": "cloud.bolt.rain.fill"}]},
                        {
                          "when": "sky contains snow or sky contains sleet or sky contains blizzard",
                          "then": [{"target": "skyIcon", "icon": "cloud.snow.fill"}]
                        },
                        {
                          "when": "sky contains rain or sky contains drizzle or sky contains shower",
                          "then": [{"target": "skyIcon", "icon": "cloud.rain.fill"}]
                        },
                        {
                          "when": "sky contains fog or sky contains mist or sky contains haze",
                          "then": [{"target": "skyIcon", "icon": "cloud.fog.fill"}]
                        },
                        {"when": "sky contains partly", "then": [{"target": "skyIcon", "icon": "cloud.sun.fill"}]},
                        {
                          "when": "sky contains overcast or sky contains cloudy",
                          "then": [{"target": "skyIcon", "icon": "cloud.fill"}]
                        }
                      ]
                    },
                    {
                      "name": "Offline",
                      "when": "temp is missing",
                      "then": [{"target": "tempText", "hide": true}, {"target": "skyIcon", "icon": "icloud.slash", "opacity": 0.6}]
                    }
                  ],
                  "board": {
                    "width": 380,
                    "blocks": [
                      {"blocks": "python3 weather.py", "every": "30m", "timeout": 25},
                      {
                        "row": [
                          {"button": "Change place", "icon": "mappin.and.ellipse", "run": "open -t place.txt"},
                          {"button": "wttr.in", "icon": "safari", "open": "https://wttr.in"}
                        ]
                      }
                    ]
                  },
                  "files": {
                    "now.sh": "#!/bin/zsh -f\n# Today's weather from wttr.in as compact JSON (format=j2, about 3 KB). Both face values run this same command,\n# so one request feeds them both; each reads its own path.\nplace=$(head -n 1 \"$SPRITE_DIR/place.txt\" 2>/dev/null | tr ' ' '+')\ncurl -fsS --max-time 12 \"https://wttr.in/${place}?format=j2\"\n",
                    "place.txt": "\n",
                    "weather.py": "#!/usr/bin/env python3\n\"\"\"The weather board from wttr.in: now, the next 24 hours as a chart, and the next days with an icon each, as MenuSprite blocks.\"\"\"\nimport json\nimport os\nimport subprocess\nfrom datetime import datetime\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nwith open(os.path.join(HERE, \"place.txt\")) as file:\n    place = file.readline().strip().replace(\" \", \"+\")\n\ndone = subprocess.run([\"curl\", \"-fsS\", \"--max-time\", \"15\", \"https://wttr.in/%s?format=j1\" % place],\n                      capture_output=True, text=True, timeout=20)\nif done.returncode != 0:\n    print(json.dumps([{\"text\": \"wttr.in did not answer\", \"font\": \"headline\", \"icon\": \"icloud.slash\"},\n                      {\"text\": done.stderr.strip()[:160].replace(\"{\", \"{\\u200b\"), \"font\": \"caption\", \"color\": \"gray\"}]))\n    raise SystemExit(0)\n\n\ndef symbol(sky):\n    \"\"\"An SF Symbol for wttr.in's description of the sky.\"\"\"\n    sky = sky.lower()\n    for words, name in (((\"thunder\",), \"cloud.bolt.rain.fill\"), ((\"snow\", \"sleet\", \"blizzard\", \"ice\"), \"cloud.snow.fill\"),\n                        ((\"rain\", \"drizzle\", \"shower\"), \"cloud.rain.fill\"), ((\"fog\", \"mist\", \"haze\"), \"cloud.fog.fill\"),\n                        ((\"partly\",), \"cloud.sun.fill\"), ((\"cloud\", \"overcast\"), \"cloud.fill\")):\n        if any(word in sky for word in words):\n            return name\n    return \"sun.max.fill\"\n\n\ndata = json.loads(done.stdout)\nnow, area = data[\"current_condition\"][0], data[\"nearest_area\"][0]\nhours = [(datetime.strptime(day[\"date\"], \"%Y-%m-%d\").replace(hour=int(h[\"time\"]) // 100), h)\n         for day in data[\"weather\"] for h in day[\"hourly\"]]\nupcoming = [h for when, h in hours if when >= datetime.now().replace(minute=0, second=0, microsecond=0)][:8]\ndays = []\nfor index, day in enumerate(data[\"weather\"]):\n    sky = day[\"hourly\"][4][\"weatherDesc\"][0][\"value\"].strip()\n    label = [\"Today\", \"Tomorrow\"][index] if index < 2 else datetime.strptime(day[\"date\"], \"%Y-%m-%d\").strftime(\"%A\")\n    days.append({\"row\": [{\"text\": label, \"icon\": symbol(sky), \"fit\": True},\n                         {\"text\": \"%s° – %s° · %s\" % (day[\"mintempC\"], day[\"maxtempC\"], sky), \"color\": \"gray\", \"lines\": 1}]})\n\nprint(json.dumps([\n    {\"row\": [\n        {\"value\": now[\"temp_C\"] + \"°\", \"caption\": area[\"areaName\"][0][\"value\"], \"font\": \"huge\",\n         \"detail\": now[\"weatherDesc\"][0][\"value\"]},\n        {\"stats\": [\n            {\"name\": \"Feels like\", \"value\": now[\"FeelsLikeC\"] + \"°\"},\n            {\"name\": \"Humidity\", \"value\": now[\"humidity\"] + \"%\"},\n            {\"name\": \"Wind\", \"value\": \"%s km/h %s\" % (now[\"windspeedKmph\"], now[\"winddir16Point\"])},\n            {\"name\": \"UV index\", \"value\": now[\"uvIndex\"]},\n        ]},\n    ]},\n    {\"card\": [\n        {\"chart\": [float(h[\"tempC\"]) for h in upcoming], \"caption\": \"Temperature, every 3 hours\", \"height\": 44, \"color\": \"orange\"},\n        {\"text\": \"Rain chance up to %d%%\" % max(int(h[\"chanceofrain\"]) for h in upcoming), \"font\": \"caption\", \"color\": \"gray\"},\n    ], \"title\": \"Next 24 hours\"},\n    {\"card\": days, \"title\": \"Next days\"},\n]))\n"
                  }
                }
                """#)
    ]
    public static func named(_ name: String) -> Example? { all.first { $0.name.caseInsensitiveCompare(name) == .orderedSame } }
}
